const fs = require('fs');

function renderFile(filePath, data = {}, cb) {
  try {
    let tpl = fs.readFileSync(filePath, 'utf8');
    tpl = tpl.replace(/<%=\s*([a-zA-Z0-9_$.]+)\s*%>/g, (_, key) => {
      return data[key] !== undefined ? String(data[key]) : '';
    });
    if (typeof cb === 'function') return cb(null, tpl);
    return tpl;
  } catch (err) {
    if (typeof cb === 'function') return cb(err);
    throw err;
  }
}

module.exports = { renderFile };
